('hero', '{"title":"Creative Productivity","subtitle":"Nexus CPN","description":"Building powerful digital tools and solutions for everyone. We craft bots, web apps, and services that simplify your digital life.","badge":"◆ Welcome ◆","cta_text":"Explore Tools","version":"v2.0.25"}'::jsonb),
